import React from 'react';

const Card = ({ text, category, color = '#00F0FF' }) => {
  return (
    <div 
      className="w-full max-w-md aspect-[3/4] bg-raw-bone p-8 flex flex-col justify-between transition-all duration-500 shadow-[20px_20px_0px_0px_rgba(0,0,0,0.1)]"
      style={{ 
        // Usamos uma variável CSS para injetar a cor na sombra de forma dinâmica
        boxShadow: `20px 20px 0px 0px ${color}` 
      }}
    >
      <div className="flex justify-between items-start">
        <span className="text-raw-onyx font-archivo text-xs uppercase tracking-tighter">
          RAW<span style={{ color: color }}>.</span> SESSION
        </span>
        
        {/* Etiqueta da categoria com a cor do modo */}
        <span 
          className="px-2 py-1 text-raw-bone text-[10px] font-bold uppercase transition-colors duration-500"
          style={{ backgroundColor: color }}
        >
          {category}
        </span>
      </div>
      
      <div className="flex-grow flex items-center">
        <h3 className="text-raw-onyx font-archivo text-3xl md:text-4xl leading-tight uppercase">
          "{text}"
        </h3>
      </div>

      <div className="border-t-2 border-raw-onyx/10 pt-4 flex justify-between items-center">
        <span className="text-[9px] text-raw-onyx/40 font-inter uppercase tracking-widest">
          Responde ou passa a vez
        </span>
        <div 
          className="w-2 h-2 rounded-full animate-pulse"
          style={{ backgroundColor: color }}
        />
      </div>
    </div>
  );
};

export default Card;
